(** [veriwasm::opiter::read_block_type]:
    Source: 'src/opiter.rs', lines 309:0-327:1 *)
Definition opiter_read_block_type
  (data : slice u8) (pos : usize) :
  result (core_result_Result_t (opiter_BlockType_t * usize) error_OpError_t)
  :=
  r <- reader_read_byte data pos;
  cf <-
    core_result_Result_Insts_CoreOpsTry_traitTryTResultInfallibleE_branch r;
  match cf with
  | Core_ops_control_flow_ControlFlow_Continue val =>
    let (b, p) := val in
    if b s= 64%u8
    then Ok (Core_result_Result_Ok (Opiter_BlockType_Empty, p))
    else
      if b s= 127%u8
      then
        Ok (Core_result_Result_Ok (Opiter_BlockType_Value Types_ValueType_I32,
          p))
      else
        if b s= 126%u8
        then
          Ok (Core_result_Result_Ok (Opiter_BlockType_Value
            Types_ValueType_I64, p))
        else
          if b s= 125%u8
          then
            Ok (Core_result_Result_Ok (Opiter_BlockType_Value
              Types_ValueType_F32, p))
          else
            if b s= 124%u8
            then
              Ok (Core_result_Result_Ok (Opiter_BlockType_Value
                Types_ValueType_F64, p))
            else Ok (Core_result_Result_Err Error_OpError_InvalidBlockType)
  | Core_ops_control_flow_ControlFlow_Break residual =>
    core_result_Result_Insts_CoreOpsTry_traitFromResidualResultInfallibleE_from_residual
      (opiter_BlockType_t * usize) (core_convert_From_Blanket error_OpError_t)
      residual
  end
.

